/* Invoice numbers that run in sequence for each store (round docs-1028): an invoice in the EU must carry a number that is unique and follows on from the store's previous one, and the PDF used to be numbered from the order's day and id ("SL-20260923-1A2B3C4D"), unique but not in sequence. New store_invoice_series (one row per store, the last number given) and store_invoice_numbers (one row per order, its number and when it was issued, unique per store), both server only (row level security on, no policy, nothing granted to anon or signed in users), and public.storelib_invoice_number(order, store), called by the server when a receipt or invoice PDF is first drawn (lib/checkout/invoice.ts): it hands out the store's next number under a lock on the store's row, so two drawings at the same moment never share or skip one, and gives the same number every time after. Orders written before this part ran keep the number their PDF already carried (store_invoice_numbering.started_at is when it first ran); until it runs every PDF is numbered as before. Safe to run again. */
create table if not exists public.store_invoice_numbering (id boolean primary key default true check (id), started_at timestamptz not null default now());
insert into public.store_invoice_numbering (id) values (true) on conflict (id) do nothing;
create table if not exists public.store_invoice_series (creator_id uuid primary key, last_seq integer not null default 0 check (last_seq >= 0), updated_at timestamptz not null default now());
create table if not exists public.store_invoice_numbers (order_id uuid primary key, creator_id uuid not null, seq integer not null check (seq > 0), issued_at timestamptz not null default now(), constraint store_invoice_numbers_creator_seq_key unique (creator_id, seq));
alter table public.store_invoice_numbering enable row level security;
alter table public.store_invoice_series enable row level security;
alter table public.store_invoice_numbers enable row level security;
revoke all on public.store_invoice_numbering from anon, authenticated;
revoke all on public.store_invoice_series from anon, authenticated;
revoke all on public.store_invoice_numbers from anon, authenticated;
create or replace function public.storelib_invoice_number(p_order uuid, p_creator uuid) returns jsonb language plpgsql security definer set search_path = public as $f$ declare v_seq integer; v_at timestamptz; v_start timestamptz; v_created timestamptz; begin if p_order is null or p_creator is null then return null; end if; select n.seq, n.issued_at into v_seq, v_at from public.store_invoice_numbers n where n.order_id = p_order; if v_seq is not null then return jsonb_build_object('seq', v_seq, 'issued_at', v_at); end if; select s.started_at into v_start from public.store_invoice_numbering s where s.id; select o.created_at into v_created from public.orders o join public.products p on p.id = o.product_id where o.id = p_order and p.creator_id = p_creator; if v_start is null or v_created is null or v_created < v_start then return null; end if; insert into public.store_invoice_series (creator_id) values (p_creator) on conflict (creator_id) do nothing; perform 1 from public.store_invoice_series s where s.creator_id = p_creator for update; select n.seq, n.issued_at into v_seq, v_at from public.store_invoice_numbers n where n.order_id = p_order; if v_seq is not null then return jsonb_build_object('seq', v_seq, 'issued_at', v_at); end if; update public.store_invoice_series s set last_seq = s.last_seq + 1, updated_at = now() where s.creator_id = p_creator returning s.last_seq into v_seq; insert into public.store_invoice_numbers (order_id, creator_id, seq) values (p_order, p_creator, v_seq) returning issued_at into v_at; return jsonb_build_object('seq', v_seq, 'issued_at', v_at); end $f$;
revoke all on function public.storelib_invoice_number(uuid, uuid) from public, anon, authenticated;
grant execute on function public.storelib_invoice_number(uuid, uuid) to service_role;
notify pgrst, 'reload schema';
